<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import {createReadGate,errorText} from './client.mjs';import {dimensions} from './media.mjs';
const props=defineProps({policy:Object,category:String,client:Object,status:Object,schedule:Object});const result=ref(null),error=ref(''),busy=ref(false),gate=createReadGate();let timer;
async function load(){if(!props.category||!props.policy.bindings[props.category])return;const read=gate.begin();busy.value=true;error.value='';result.value=null;try{const r=await props.client.post('/configuration/policy-summary',{config_revision:props.status.current.value.revision,runtime_generation:props.status.health.value.generation,policy:props.policy,category_id:props.category});if(read.current())result.value=r.result}catch(e){if(read.current())error.value=errorText(e)}finally{if(read.current())busy.value=false}}
watch(()=>JSON.stringify([props.policy,props.category,props.status.current.value?.revision]),()=>{gate.begin();result.value=null;clearTimeout(timer);timer=setTimeout(load,250)},{immediate:true});onBeforeUnmount(()=>{clearTimeout(timer);gate.close()});
</script>
<template><section class="sb-policy-reference"><p v-if="busy" role="status">正在读取当前草稿的策略摘要…</p><p v-if="error" role="alert">策略摘要暂时无法加载。<VBtn variant="text" @click="load">重新加载</VBtn></p><template v-if="result"><details class="sb-help"><summary>查看所选策略的细节</summary><p>允许 {{result.summary.resolutions.map(r=>r===2160?'4K':r+'p').join('、')}}；按 {{result.summary.comparison.map(r=>dimensions[r.dimension]).join(' › ')}} 依次比较。</p><p class="sb-muted">发布组：{{result.summary.group}} · 片源：{{result.summary.source}}<template v-if="Object.keys(result.locks).length"> · {{Object.keys(result.locks).length}} 项锁定条件</template><template v-if="result.custom_rules.length||result.custom_admission"> · 含自定义准入条件</template></p><p v-if="schedule">候选观察{{schedule.observation_enabled?'已启用':'未启用'}} · 升级冷却{{schedule.cooldown_enabled?'已启用':'未启用'}} · {{schedule.supersession_limit===0?'禁止自动替换':'最多替换 '+schedule.supersession_limit+' 次'}}</p><small>此处显示当前草稿，保存后生效。</small></details><p v-if="schedule?.observation_enabled&&[schedule.base_seconds,schedule.quiet_seconds,schedule.max_seconds].some(v=>v==null)" role="alert">候选观察已启用，但时间参数不完整，请在搜索与调度中补齐。</p></template></section></template>
